\section*{Question 1}

Let \(f\) be the function given by \(f(x)=4 x^{2}-x^{3}\), and let \(\ell\) be the line \(y=18-3 x\), where \(\ell\) is tangent to the graph of \(f\). Let \(R\) be the region bounded by the graph of \(f\) and the \(x\)-axis, and let \(S\) be the region bounded by the graph of \(f\), the line \(\ell\), and the \(x\)-axis, as shown above.
\begin{itemize}
\item[(a)] Show that \(\ell\) is tangent to the graph of \(y=f(x)\) at the point \(x=3\).
\end{itemize}
![](https://cdn.mathpix.com/cropped/d30ff589-407b-4fd9-bc94-803d9d42adcd-1.jpg?height=382&width=795&top_left_y=378&top_left_x=1164)
\begin{itemize}
\item[(b)] Find the area of \(S\).
\item[(c)] Find the volume of the solid generated when \(R\) is revolved about the \(x\)-axis.
\item[(a)]
\[
\begin{aligned}
& f^{\prime}(x)=8 x-3 x^{2} ; f^{\prime}(3)=24-27=-3 \\
& f(3)=36-27=9
\end{aligned}
\]
Tangent line at \(x=3\) is
\[
y=-3(x-3)+9=-3 x+18,
\]
which is the equation of line \(\ell\).
\item[(b)]
\[
\begin{aligned}
& f(x)=0 \text { at } x=4 \\
& \text { The line intersects the } x \text {-axis at } x= \\
& \text { Area }=\frac{1}{2}(3)(9)-\int_{3}^{4}\left(4 x^{2}-x^{3}\right) d x \\
& \quad=7.916 \text { or } 7.917
\end{aligned}
\]
OR
\[
\begin{aligned}
\text { Area }= & \int_{3}^{4}\left((18-3 x)-\left(4 x^{2}-x^{3}\right)\right) d x \\
& +\frac{1}{2}(2)(18-12) \\
= & 7.916 \text { or } 7.917
\end{aligned}
\]
\end{itemize}
\(2:\left\{\begin{array}{c}1: \text { finds } f^{\prime}(3) \text { and } f(3) \\ 1:\left\{\begin{array}{c}\text { finds equation of tangent line } \\ \text { or } \\ \text { shows }(3,9) \text { is on both the } \\ \text { graph of } f \text { and line } \ell\end{array}\right.\end{array}\right.\)
\(4:\left\{\begin{aligned} 2 & : \text { integral for non-triangular region } \\ & 1: \text { limits } \\ & 1: \text { integrand } \\ & 1: \text { area of triangular region } \\ & 1: \text { answer }\end{aligned}\right.\)
\begin{itemize}
\item[(c)]
\[
\begin{aligned}
\text { Volume } & =\pi \int_{0}^{4}\left(4 x^{2}-x^{3}\right)^{2} d x \\
& =156.038 \pi \text { or } 490.208
\end{aligned}
\]
\end{itemize}
